# Old EngConnect status -> BUNYAH status. Every value has a reverse mapping in downgrade().
PROJECT_STATUS_UP = {"open": "published", "awaiting_payment": "proposal_accepted"}
PROJECT_STATUS_DOWN = {
    "draft": "open", "published": "open", "applications_closed": "open", "under_evaluation": "open",
    "shortlisted": "open", "proposal_accepted": "awaiting_payment", "resubmitted": "submitted",
    "approved": "submitted", "disputed": "in_progress",
}
OFFER_STATUS_UP = {"pending": "submitted"}
OFFER_STATUS_DOWN = {"submitted": "pending", "shortlisted": "pending", "clarification_requested": "pending"}


def _migrate_data_up() -> None:
    """Converts existing EngConnect data. Nothing is deleted; old tables (payments, reviews...) stay as they are."""
    bind = op.get_bind()
    for old, new in PROJECT_STATUS_UP.items():
        bind.execute(sa.text("UPDATE projects SET status=:n WHERE status=:o"), {"n": new, "o": old})
    for old, new in OFFER_STATUS_UP.items():
        bind.execute(sa.text("UPDATE offers SET status=:n WHERE status=:o"), {"n": new, "o": old})
    bind.execute(sa.text("UPDATE projects SET work_mode='remote' WHERE work_mode='online'"))
    bind.execute(sa.text("UPDATE projects SET published_at=created_at WHERE status <> 'draft'"))
    # Files: which record each one belongs to (decides who may download it).
    bind.execute(sa.text("UPDATE files SET context_type='portfolio' WHERE kind='portfolio'"))
    bind.execute(sa.text("UPDATE files SET context_id=project_id WHERE project_id IS NOT NULL"))

    # Every old studio office becomes an organization whose owner is that account.
    offices = bind.execute(sa.text("SELECT id, name, company_name, bio, location, website FROM users "
                                   "WHERE role='office'")).fetchall()
    for u in offices:
        res = bind.execute(sa.text(
            "INSERT INTO organizations (name, name_ar, org_type, cr_number, license_info, city, address, "
            "contact_email, contact_phone, representative_name, representative_title, description, website, "
            "verification_status, is_demo, created_at) VALUES (:name, '', 'engineering_firm', '', '', :city, '', "
            "'', '', :rep, '', :descr, :web, 'unverified', :f, :now) RETURNING id"),
            {"name": u.company_name or u.name, "city": u.location or "", "rep": u.name, "descr": u.bio or "",
             "web": u.website or "", "f": False, "now": _now()})
        org_id = res.scalar()
        bind.execute(sa.text("INSERT INTO org_members (org_id, user_id, org_role, is_active, created_at) "
                             "VALUES (:o, :u, 'owner', :t, :now)"), {"o": org_id, "u": u.id, "t": True, "now": _now()})
        bind.execute(sa.text("UPDATE projects SET org_id=:o WHERE office_id=:u"), {"o": org_id, "u": u.id})
        bind.execute(sa.text("UPDATE conversations SET org_id=:o WHERE office_id=:u"), {"o": org_id, "u": u.id})

    # Every old freelancer gets an engineer profile filled from the old profile fields.
    freelancers = bind.execute(sa.text("SELECT id, headline, bio, location, skills FROM users "
                                       "WHERE role='freelancer'")).fetchall()
    for u in freelancers:
        bind.execute(sa.text(
            "INSERT INTO engineer_profiles (user_id, title, specializations, years_experience, education, "
            "qualifications, certifications, registration_body, registration_number, software_skills, languages, "
            "city, availability, work_preference, bio, verification_status, is_demo, updated_at) VALUES "
            "(:id, :title, '', 0, '', '', '', '', '', :skills, '', :city, 'available', 'hybrid', :bio, "
            "'unverified', :f, :now)"),
            {"id": u.id, "title": u.headline or "", "skills": u.skills or "", "city": u.location or "",
             "bio": u.bio or "", "f": False, "now": _now()})
    bind.execute(sa.text("UPDATE users SET role='organization' WHERE role='office'"))
    bind.execute(sa.text("UPDATE users SET role='engineer' WHERE role='freelancer'"))

    # Old one-way reviews are copied (not moved) into the new two-way ratings table.
    reviews = bind.execute(sa.text("SELECT r.id, r.project_id, r.office_id, r.freelancer_id, r.rating, r.text, "
                                   "r.created_at, p.org_id FROM reviews r JOIN projects p ON p.id=r.project_id"))
    for r in reviews.fetchall():
        if r.org_id is None:
            continue
        bind.execute(sa.text(
            "INSERT INTO ratings (subject_key, subject_type, project_id, reviewer_id, reviewer_side, org_id, "
            "engineer_id, rating, text, created_at) VALUES (:k, 'project', :p, :rv, 'organization', :o, :e, :ra, "
            ":t, :c)"),
            {"k": f"project:{r.project_id}:organization", "p": r.project_id, "rv": r.office_id, "o": r.org_id,
             "e": r.freelancer_id, "ra": r.rating, "t": r.text or "", "c": r.created_at})


def _now():
    from datetime import UTC, datetime
    return datetime.now(UTC)


def _migrate_data_down() -> None:
    bind = op.get_bind()
    bind.execute(sa.text("UPDATE users SET role='office' WHERE role='organization'"))
    bind.execute(sa.text("UPDATE users SET role='freelancer' WHERE role='engineer'"))
    # Admin accounts created in BUNYAH have no EngConnect equivalent; they become offices without projects.
    bind.execute(sa.text("UPDATE users SET role='office' WHERE role='admin'"))
    for new, old in PROJECT_STATUS_DOWN.items():
        bind.execute(sa.text("UPDATE projects SET status=:o WHERE status=:n"), {"n": new, "o": old})
    for new, old in OFFER_STATUS_DOWN.items():
        bind.execute(sa.text("UPDATE offers SET status=:o WHERE status=:n"), {"n": new, "o": old})
    bind.execute(sa.text("UPDATE projects SET work_mode='online' WHERE work_mode IN ('remote','hybrid')"))
    # Rows that only exist in BUNYAH (e.g. events of service requests) are removed with their tables.
    bind.execute(sa.text("DELETE FROM project_events WHERE project_id IS NULL"))
    bind.execute(sa.text("UPDATE files SET data=X'' WHERE data IS NULL"))


def downgrade() -> None:
    """Goes back to the EngConnect structure. BUNYAH-only records (organizations, contracts, simulated
    finance...) are dropped with their tables, so take a database backup before downgrading."""
    _migrate_data_down()
